-- ============================================================
-- Migración 097: listas de chequeo del mantenimiento biomédico, configurables por tipo de equipo
--
-- SISRES: Inventario → Configurar → Listas de chequeo (mostrarChecklistMantenimiento.php, tabla
-- mantenimiento_checklist, sql/checklist_mantenimiento_2026-07-31.sql). Cada tipo de equipo tiene su lista de ítems;
-- el formulario de mantenimiento la muestra según el nombre del equipo y guarda en biomedical_maintenance.chk_items
-- {"ítem": 1 cumple | 0 no cumple}, chk_total y chk_marcados (columnas que ya existen desde la 040).
--
-- `equipo` es la clave normalizada del nombre (mayúsculas, sin tildes, espacios → _), igual que normalizarEquipo() de
-- SISRES (src/lib/biomedico-checklist.ts). La fila GENERAL es la lista para equipos sin una propia.
--
-- Semilla: las 47 listas vigentes de SISRES. ON CONFLICT DO NOTHING: re-ejecutar no pisa lo que se haya
-- editado después desde la aplicación.
--
-- Quién puede qué: leer, los roles que ven Equipos biomédicos; crear/editar/eliminar, ADMIN y MANTENIMIENTO
-- (en SISRES, el cargo Coordinador; el Analista solo las ve). Idempotente.
-- ============================================================

CREATE TABLE IF NOT EXISTS biomedical_checklists (
  equipo     VARCHAR(150) PRIMARY KEY CHECK (equipo ~ '^[A-Z0-9_]+$'),
  items      JSONB NOT NULL CHECK (jsonb_typeof(items) = 'array' AND jsonb_array_length(items) > 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID REFERENCES auth.users(id)
);

ON CONFLICT (equipo) DO NOTHING;

ALTER TABLE biomedical_checklists ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS biomedical_checklists_select ON biomedical_checklists;
CREATE POLICY biomedical_checklists_select ON biomedical_checklists
  FOR SELECT TO authenticated
  USING (get_user_role() IN ('ADMIN','MANTENIMIENTO','COORDINACION','GERENCIAL','ANALISTA','VISTA'));

DROP POLICY IF EXISTS biomedical_checklists_write ON biomedical_checklists;
CREATE POLICY biomedical_checklists_write ON biomedical_checklists
  FOR ALL TO authenticated
  USING (get_user_role() IN ('ADMIN','MANTENIMIENTO'))
  WITH CHECK (get_user_role() IN ('ADMIN','MANTENIMIENTO'));

-- Igual que la 086: si existe la política restrictiva de TECNICO/AEROPUERTO (076), esta tabla también queda cubierta.
DO $$
BEGIN
  IF to_regprocedure('public.aplicar_politica_rol_restringido(text)') IS NOT NULL THEN
    PERFORM public.aplicar_politica_rol_restringido('biomedical_checklists');
  END IF;
END $$;
